def rpn_eval(tokens):
    def op(symbol, a, b):
        return {
            '+': lambda a, b: a + b,
            '-': lambda a, b: a - b,
            '*': lambda a, b: a * b,
            '/': lambda a, b: a / b
        }[symbol](a, b)

    stack = []

    for token in tokens:
        if isinstance(token, (float, int)):
            stack.append(token)
        else:
            b = stack.pop()
            a = stack.pop()
            stack.append(
                op(token, a, b)
            )

    return stack.pop()


