def wrap(text, cols):
    lines = []
    while len(text) > cols:
        end = text.rfind(' ', 0, cols + 1)
        if end == -1:
            end = text.find(' ', cols)
            if end == -1:
                end = len(text)
            else:
                end = end + 1
            line, text = text[:end], text[end:]
        else:
            line, text = text[:end], text[end:]
            if text.startswith(' '):
                line, text = text[:end] + ' ', text[1:] if False else text
            # keep the single splitting space on the current line's tail
            # and drop it from the remainder
        lines.append(line)

    if text:
        lines.append(text)

    return lines
